/* mlua.h -- core declarations for a Lua 5.5 compatible interpreter.
** Written from scratch for the reimplementation benchmark.
*/
#ifndef MLUA_H
#define MLUA_H

#include <stddef.h>
#include <stdint.h>
#include <setjmp.h>
#include <stdio.h>

#define MLUA_VERSION_MAJOR "5"
#define MLUA_VERSION_MINOR "5"
#define MLUA_RELEASE_NUM   "5.5.1"
#define MLUA_VERSION       "Lua " MLUA_VERSION_MAJOR "." MLUA_VERSION_MINOR
#define MLUA_COPYRIGHT     MLUA_VERSION "  Copyright (C) 1994-2026 Lua.org, PUC-Rio"

typedef int64_t  lint;
typedef double   lnum;

/* ---- value tags ---- */
#define T_NIL      0
#define T_FALSE    1
#define T_TRUE     2
#define T_INT      3
#define T_FLT      4
#define T_STR      5
#define T_TAB      6
#define T_FUN      7   /* Lua closure */
#define T_CFUN     8   /* C closure */
#define T_USERDATA 9
#define T_THREAD   10
#define T_LIGHTUD  11

typedef struct GCObj GCObj;
typedef struct Str Str;
typedef struct Table Table;
typedef struct Proto Proto;
typedef struct Closure Closure;
typedef struct CClosure CClosure;
typedef struct Udata Udata;
typedef struct lua_State lua_State;
typedef struct GlobalState GlobalState;

typedef struct Value {
  union {
    lint i;
    lnum n;
    GCObj *gc;
    void *p;
  } u;
  uint8_t tt;
} Value;

typedef int (*CFunc)(lua_State *L);

/* GC header, first member of every collectable object */
struct GCObj {
  GCObj *next;
  uint8_t tt;
  uint8_t mark;      /* 0=white 1=gray/black */
  uint8_t fin;       /* has finalizer pending / already finalized */
};

struct Str {
  GCObj h;
  uint8_t shrt;      /* interned short string */
  uint8_t extra;     /* reserved word index+1, or 0 */
  uint32_t hash;
  size_t len;
  Str *hnext;        /* intern table chain */
  char *s;           /* points to inline data */
};

typedef struct Node {
  Value key;
  Value val;
  int32_t next;      /* offset to next node in chain, 0 = none */
} Node;

struct Table {
  GCObj h;
  uint8_t flags;     /* cached absent metamethods */
  Value *arr;        /* array part 1..asize */
  uint32_t asize;
  uint32_t alimit;   /* number of used array slots hint */
  Node *node;
  uint32_t lsizenode;/* log2 of node size, node==dummy when 0 size */
  uint32_t nodesize;
  int32_t lastfree;
  Table *meta;
};

typedef struct Upval {
  GCObj h;
  Value *v;          /* points to stack or to own storage */
  Value closed;
} Upval;

typedef struct LocVar {
  Str *name;
  int startpc, endpc;
} LocVar;

typedef struct UpvalDesc {
  Str *name;
  uint8_t instack;
  uint8_t idx;
} UpvalDesc;

typedef struct AbsLine { int pc; int line; } AbsLine;

struct Proto {
  GCObj h;
  uint8_t is_vararg;
  int numparams;
  int maxstack;
  uint32_t *code;
  int ncode;
  int *lineinfo;      /* line per instruction */
  Value *k;
  int nk;
  Proto **p;          /* nested protos */
  int np;
  UpvalDesc *upvals;
  int nupvals;
  LocVar *locvars;
  int nlocvars;
  Str *source;
  int linedefined, lastlinedefined;
};

struct Closure {
  GCObj h;
  Proto *p;
  int nupvals;
  Upval *upvals[1];
};

struct CClosure {
  GCObj h;
  CFunc f;
  Str *name;          /* for error messages (optional) */
  int nupvals;
  Value upvals[1];
};

struct Udata {
  GCObj h;
  Table *meta;
  size_t len;         /* size of user memory */
  int nuser;          /* number of user values */
  Value *uv;
  void *data;
};

/* call info */
typedef struct CallInfo {
  Value *func;        /* stack index of function */
  Value *base;        /* first local */
  Value *top;         /* top of frame stack space */
  const uint32_t *savedpc;
  int nresults;
  int callstatus;
  int nextraargs;     /* for vararg functions */
  struct CallInfo *prev, *next;
  const char *cname;  /* name for C functions in traceback */
  const char *cwhat;
} CallInfo;

#define CIST_LUA    1
#define CIST_HOOKED 2
#define CIST_FIN    4    /* running a finalizer */
#define CIST_TAIL   8
#define CIST_MMCALL 16   /* called from a metamethod */

/* error jump buffer */
typedef struct ErrJmp {
  struct ErrJmp *prev;
  jmp_buf b;
  volatile int status;
} ErrJmp;

#define COS_RUN   0
#define COS_SUSP  1
#define COS_NORM  2
#define COS_DEAD  3

struct lua_State {
  GCObj h;
  GlobalState *G;
  Value *stack;
  Value *stack_last;
  Value *top;
  size_t stacksize;
  CallInfo base_ci;
  CallInfo *ci;
  ErrJmp *errjmp;
  int nci;
  int ncalls;         /* nested C calls */
  Upval *openupval;   /* list of open upvalues (sorted by level desc) */
  struct lua_State *caller;   /* who resumed us */
  int status;         /* coroutine status */
  int coroutine;      /* is a coroutine (not main) */
  void *ctx;          /* resume context */
  Value errval;
  struct Tbc *tbclist;
  int nresumeres;
};

typedef struct Tbc { struct Tbc *prev; Value *v; } Tbc;

typedef struct StrTable {
  Str **hash;
  uint32_t size;
  uint32_t nuse;
} StrTable;

struct GlobalState {
  GCObj *allgc;
  GCObj *finobj;      /* objects with finalizers */
  GCObj *tobefnz;
  size_t totalbytes;
  size_t gcthreshold;
  int gcrunning;
  int gcstopped;
  int gcemergency;
  int gcpause;        /* percentage */
  int gcstepmul;
  StrTable strt;
  Value registry;     /* a table */
  Table *globals;
  Table *stringmeta;
  Str *tmname[32];
  lua_State *mainthread;
  lua_State *current;
  Value nilvalue;
  Str *memerrmsg;
  unsigned int seed;
  uint64_t rngstate[4];
  int warnon;
  char *warnbuf;
  size_t warnlen, warncap;
  int inGC;
  GCObj **grayroots; int ngray, graycap;
  int panic;
};

/* metamethod indices */
enum {
  TM_INDEX, TM_NEWINDEX, TM_GC, TM_MODE, TM_LEN, TM_EQ,
  TM_ADD, TM_SUB, TM_MUL, TM_MOD, TM_POW, TM_DIV, TM_IDIV,
  TM_BAND, TM_BOR, TM_BXOR, TM_SHL, TM_SHR,
  TM_UNM, TM_BNOT, TM_LT, TM_LE, TM_CONCAT, TM_CALL, TM_CLOSE,
  TM_TOSTRING, TM_NAME, TM_PAIRS, TM_N
};

/* ---- value helpers ---- */
#define ttype(o)     ((o)->tt)
#define isnil(o)     ((o)->tt == T_NIL)
#define isbool(o)    ((o)->tt == T_FALSE || (o)->tt == T_TRUE)
#define isfalsey(o)  ((o)->tt == T_NIL || (o)->tt == T_FALSE)
#define istruthy(o)  (!isfalsey(o))
#define isint(o)     ((o)->tt == T_INT)
#define isflt(o)     ((o)->tt == T_FLT)
#define isnum(o)     ((o)->tt == T_INT || (o)->tt == T_FLT)
#define isstr(o)     ((o)->tt == T_STR)
#define istab(o)     ((o)->tt == T_TAB)
#define isfun(o)     ((o)->tt == T_FUN || (o)->tt == T_CFUN)
#define iscollectable(o) ((o)->tt >= T_STR && (o)->tt != T_LIGHTUD)

#define ivalue(o)    ((o)->u.i)
#define fltvalue(o)  ((o)->u.n)
#define numvalue(o)  (isint(o) ? (lnum)ivalue(o) : fltvalue(o))
#define strvalue(o)  ((Str *)(o)->u.gc)
#define tabvalue(o)  ((Table *)(o)->u.gc)
#define clvalue(o)   ((Closure *)(o)->u.gc)
#define cclvalue(o)  ((CClosure *)(o)->u.gc)
#define udvalue(o)   ((Udata *)(o)->u.gc)
#define thvalue(o)   ((lua_State *)(o)->u.gc)
#define gcvalue(o)   ((o)->u.gc)

static inline Value mknil(void) { Value v; v.tt = T_NIL; v.u.i = 0; return v; }
static inline Value mkbool(int b) { Value v; v.tt = b ? T_TRUE : T_FALSE; v.u.i = 0; return v; }
static inline Value mkint(lint i) { Value v; v.tt = T_INT; v.u.i = i; return v; }
static inline Value mkflt(lnum n) { Value v; v.tt = T_FLT; v.u.n = n; return v; }
static inline Value mkgc(GCObj *o, int tt) { Value v; v.tt = tt; v.u.gc = o; return v; }
static inline Value mkstr(Str *s) { return mkgc((GCObj*)s, T_STR); }
static inline Value mktab(Table *t) { return mkgc((GCObj*)t, T_TAB); }
static inline Value mkp(void *p) { Value v; v.tt = T_LIGHTUD; v.u.p = p; return v; }

/* ---- memory ---- */
void *m_alloc(lua_State *L, size_t n);
void *m_realloc(lua_State *L, void *p, size_t osz, size_t nsz);
void m_free(lua_State *L, void *p, size_t sz);
#define m_new(L,t)      ((t *)m_alloc(L, sizeof(t)))
#define m_newvec(L,n,t) ((t *)m_alloc(L, (n) * sizeof(t)))
#define m_freevec(L,p,n,t) m_free(L, p, (n)*sizeof(t))

/* ---- strings ---- */
Str *str_newl(lua_State *L, const char *s, size_t len);
Str *str_new(lua_State *L, const char *s);
Str *str_fmt(lua_State *L, const char *fmt, ...);
int  str_eq(Str *a, Str *b);
uint32_t str_hash(const char *s, size_t l, uint32_t seed);
void strt_init(lua_State *L);
void strt_remove(GlobalState *g, Str *s);

/* ---- tables ---- */
Table *tab_new(lua_State *L);
Table *tab_newsz(lua_State *L, int narr, int nrec);
void tab_free(lua_State *L, Table *t);
const Value *tab_get(Table *t, const Value *k);
const Value *tab_getstr(Table *t, Str *k);
const Value *tab_getint(Table *t, lint k);
void tab_set(lua_State *L, Table *t, const Value *k, const Value *v);
void tab_setstr(lua_State *L, Table *t, Str *k, const Value *v);
void tab_setint(lua_State *L, Table *t, lint k, const Value *v);
lint tab_len(Table *t);
int tab_next(lua_State *L, Table *t, Value *key, Value *out);
void tab_resize(lua_State *L, Table *t, uint32_t nasize, uint32_t nhsize);

/* ---- object creation ---- */
Closure *cl_new(lua_State *L, Proto *p);
CClosure *ccl_new(lua_State *L, CFunc f, int nup);
Proto *proto_new(lua_State *L);
Udata *ud_new(lua_State *L, size_t sz, int nuser);
lua_State *th_new(lua_State *L);

/* ---- GC ---- */
void gc_step(lua_State *L);
void gc_full(lua_State *L, int isemergency);
void gc_checkfin(lua_State *L, Value *o, Table *mt);
void gc_freeall(lua_State *L);
#define gc_check(L) do { \
  if ((L)->G->totalbytes >= (L)->G->gcthreshold && !(L)->G->gcstopped) gc_step(L); } while (0)

/* ---- state ---- */
lua_State *lua_open(void);
void lua_close_state(lua_State *L);

/* ---- errors ---- */
void l_error(lua_State *L, const char *fmt, ...);      /* adds position */
void l_errorraw(lua_State *L, Value v);
void l_throw(lua_State *L, int status);
int  l_pcall(lua_State *L, void (*f)(lua_State *, void *), void *ud);
const char *l_where(lua_State *L, int level, char *buf, size_t bsz);
void l_typeerror(lua_State *L, const Value *o, const char *op);
const char *typename_of(const Value *o);
const char *typenamestr(int tt);

/* ---- VM ---- */
void vm_call(lua_State *L, Value *func, int nargs, int nresults);
int  vm_pcall(lua_State *L, Value *func, int nargs, int nresults, ptrdiff_t errf);
void vm_execute(lua_State *L, CallInfo *ci);
int  vm_precall(lua_State *L, Value *func, int nresults);
void vm_arith(lua_State *L, int op, const Value *a, const Value *b, Value *res);
int  vm_equal(lua_State *L, const Value *a, const Value *b);
int  vm_lessthan(lua_State *L, const Value *a, const Value *b);
int  vm_lessequal(lua_State *L, const Value *a, const Value *b);
void vm_gettable(lua_State *L, const Value *t, const Value *k, Value *res);
void vm_settable(lua_State *L, const Value *t, const Value *k, const Value *v);
void vm_concat(lua_State *L, int n);
void vm_len(lua_State *L, const Value *o, Value *res);
void vm_tostring(lua_State *L, const Value *o, Value *res);
Table *get_metatable(lua_State *L, const Value *o);
const Value *get_metamethod(lua_State *L, const Value *o, int tm);
const Value *tab_getmeta(lua_State *L, Table *mt, int tm);
void grow_stack(lua_State *L, int n);
void checkstack(lua_State *L, int n);
#define ensurestack(L,n) do { if ((L)->top + (n) > (L)->stack_last) grow_stack(L, n); } while (0)

/* conversions */
int  v_tonumber(const Value *o, lnum *out);
int  v_tointeger(const Value *o, lint *out);
int  v_tointeger_ex(const Value *o, lint *out, int mode); /* mode: 0 floor-exact, 1 floor, 2 ceil */
int  str2num(const char *s, size_t len, Value *out);
size_t num2str(char *buf, size_t bsz, const Value *o);
Str *v_tostr(lua_State *L, const Value *o);
int flt2int(lnum n, lint *out, int mode);

/* lexer/parser */
Closure *parse_chunk(lua_State *L, const char *src, size_t len, const char *chunkname,
                     const char *mode, Value *env);

/* ---- API-ish helpers used by libraries ---- */
void lib_open(lua_State *L);
void push(lua_State *L, Value v);
Value *stackat(lua_State *L, int idx);   /* 1-based arg index within current frame */
int nargs(lua_State *L);

/* debug/traceback */
void db_traceback(lua_State *L, lua_State *L1, const char *msg, int level);
int getfuncname(lua_State *L, CallInfo *ci, const char **name, const char **what);
int currentline(CallInfo *ci);
const char *chunkid(char *out, size_t osz, const char *source, size_t srclen);

/* library openers */
int open_base(lua_State *L);
int open_string(lua_State *L);
int open_table(lua_State *L);
int open_math(lua_State *L);
int open_os(lua_State *L);
int open_io(lua_State *L);
int open_coroutine(lua_State *L);
int open_debug(lua_State *L);
int open_utf8(lua_State *L);
int open_package(lua_State *L);

/* argument checking helpers */
lint    arg_int(lua_State *L, int i);
lint    arg_optint(lua_State *L, int i, lint def);
lnum    arg_num(lua_State *L, int i);
lnum    arg_optnum(lua_State *L, int i, lnum def);
const char *arg_str(lua_State *L, int i, size_t *len);
const char *arg_optstr(lua_State *L, int i, const char *def, size_t *len);
Table  *arg_table(lua_State *L, int i);
void    arg_check(lua_State *L, int cond, int i, const char *msg);
void    arg_error(lua_State *L, int i, const char *msg);
void    arg_typeerror(lua_State *L, int i, const char *tname);
Value  *arg_any(lua_State *L, int i);
int     arg_optbool(lua_State *L, int i, int def);
void    reg_funcs(lua_State *L, Table *t, const struct luaLReg *l);
struct luaLReg { const char *name; CFunc f; };
Table *new_lib(lua_State *L, const char *name, const struct luaLReg *l);

const char *find_field_name(lua_State *L, Value *fn, char *buf, size_t bsz);

extern const char *const tmnames[];

#define MAXSTACK      1000000
#define STACK_EXTRA   5
#define MAXCCALLS     200
#define LUAI_MAXSHORTLEN 40

#endif

