/* mem.c -- memory management, GC, string interning, object construction */
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <stdio.h>
#include "mlua.h"

/* ------------------------------------------------------------------ */
/* memory                                                              */
/* ------------------------------------------------------------------ */

static void memerror(lua_State *L) {
  if (L && L->G && L->G->memerrmsg) {
    l_errorraw(L, mkstr(L->G->memerrmsg));
  }
  fprintf(stderr, "not enough memory\n");
  exit(1);
}

void *m_alloc(lua_State *L, size_t n) {
  void *p;
  if (n == 0) return NULL;
  p = malloc(n);
  if (p == NULL) {
    if (L) { gc_full(L, 1); p = malloc(n); }
    if (p == NULL) memerror(L);
  }
  if (L) L->G->totalbytes += n;
  return p;
}

void *m_realloc(lua_State *L, void *p, size_t osz, size_t nsz) {
  void *q;
  if (nsz == 0) { free(p); if (L) L->G->totalbytes -= osz; return NULL; }
  q = realloc(p, nsz);
  if (q == NULL) {
    if (L) { gc_full(L, 1); q = realloc(p, nsz); }
    if (q == NULL) memerror(L);
  }
  if (L) L->G->totalbytes += nsz - osz;
  return q;
}

void m_free(lua_State *L, void *p, size_t sz) {
  if (p == NULL) return;
  free(p);
  if (L) L->G->totalbytes -= sz;
}

/* ------------------------------------------------------------------ */
/* strings                                                             */
/* ------------------------------------------------------------------ */

uint32_t str_hash(const char *s, size_t l, uint32_t seed) {
  uint32_t h = seed ^ (uint32_t)l;
  size_t i;
  for (i = 0; i < l; i++)
    h ^= ((h << 5) + (h >> 2) + (unsigned char)s[i]);
  return h;
}

static uint32_t longhash(const char *s, size_t l, uint32_t seed) {
  /* hash a sample of the string for long strings */
  size_t step = (l >> 5) + 1;
  uint32_t h = seed ^ (uint32_t)l;
  size_t i;
  for (i = l; i >= step; i -= step)
    h ^= ((h << 5) + (h >> 2) + (unsigned char)s[i - 1]);
  return h;
}

static Str *newstrobj(lua_State *L, const char *s, size_t len, int shrt, uint32_t hash) {
  Str *ts = (Str *)m_alloc(L, sizeof(Str) + len + 1);
  ts->h.tt = T_STR; ts->h.mark = 0; ts->h.fin = 0;
  ts->shrt = (uint8_t)shrt; ts->extra = 0;
  ts->hash = hash; ts->len = len; ts->hnext = NULL;
  ts->s = (char *)(ts + 1);
  if (len) memcpy(ts->s, s, len);
  ts->s[len] = '\0';
  ts->h.next = L->G->allgc; L->G->allgc = (GCObj *)ts;
  return ts;
}

static void strt_resize(lua_State *L, uint32_t newsize) {
  StrTable *st = &L->G->strt;
  Str **nh = m_newvec(L, newsize, Str *);
  uint32_t i;
  for (i = 0; i < newsize; i++) nh[i] = NULL;
  for (i = 0; i < st->size; i++) {
    Str *p = st->hash[i];
    while (p) {
      Str *nx = p->hnext;
      uint32_t j = p->hash & (newsize - 1);
      p->hnext = nh[j]; nh[j] = p;
      p = nx;
    }
  }
  m_freevec(L, st->hash, st->size, Str *);
  st->hash = nh; st->size = newsize;
}

void strt_init(lua_State *L) {
  StrTable *st = &L->G->strt;
  st->size = 0; st->nuse = 0; st->hash = NULL;
  strt_resize(L, 256);
}

void strt_remove(GlobalState *g, Str *s) {
  StrTable *st = &g->strt;
  Str **p = &st->hash[s->hash & (st->size - 1)];
  while (*p != s) p = &(*p)->hnext;
  *p = s->hnext;
  st->nuse--;
}

Str *str_newl(lua_State *L, const char *s, size_t len) {
  GlobalState *g = L->G;
  if (len <= LUAI_MAXSHORTLEN) {
    uint32_t h = str_hash(s, len, g->seed);
    StrTable *st = &g->strt;
    Str **list = &st->hash[h & (st->size - 1)];
    Str *ts;
    for (ts = *list; ts; ts = ts->hnext) {
      if (ts->len == len && memcmp(ts->s, s, len) == 0) {
        if (ts->h.mark == 2) ts->h.mark = 0;  /* resurrect */
        return ts;
      }
    }
    if (st->nuse >= st->size && st->size < (1u << 30)) {
      strt_resize(L, st->size * 2);
      list = &st->hash[h & (st->size - 1)];
    }
    ts = newstrobj(L, s, len, 1, h);
    ts->hnext = *list; *list = ts;
    st->nuse++;
    return ts;
  } else {
    return newstrobj(L, s, len, 0, longhash(s, len, g->seed));
  }
}

Str *str_new(lua_State *L, const char *s) { return str_newl(L, s, strlen(s)); }

int str_eq(Str *a, Str *b) {
  if (a == b) return 1;
  if (a->shrt || b->shrt) return 0;
  return a->len == b->len && memcmp(a->s, b->s, a->len) == 0;
}

/* simple formatted string creator: supports %s %d %f %c %p %% and %U */
Str *str_fmt(lua_State *L, const char *fmt, ...) {
  char buf[512];
  char *b = buf;
  size_t cap = sizeof(buf), n = 0;
  va_list ap;
  va_start(ap, fmt);
  for (;;) {
    const char *e = strchr(fmt, '%');
    size_t seg = e ? (size_t)(e - fmt) : strlen(fmt);
    if (n + seg + 64 > cap) {
      size_t ncap = (n + seg + 64) * 2;
      char *nb = (char *)malloc(ncap);
      memcpy(nb, b, n);
      if (b != buf) free(b);
      b = nb; cap = ncap;
    }
    memcpy(b + n, fmt, seg); n += seg;
    if (!e) break;
    fmt = e + 1;
    switch (*fmt) {
      case 's': {
        const char *s = va_arg(ap, const char *);
        size_t l;
        if (s == NULL) s = "(null)";
        l = strlen(s);
        if (n + l + 64 > cap) {
          size_t ncap = (n + l + 64) * 2;
          char *nb = (char *)malloc(ncap);
          memcpy(nb, b, n);
          if (b != buf) free(b);
          b = nb; cap = ncap;
        }
        memcpy(b + n, s, l); n += l;
        break;
      }
      case 'd': n += sprintf(b + n, "%d", va_arg(ap, int)); break;
      case 'I': n += sprintf(b + n, "%lld", (long long)va_arg(ap, lint)); break;
      case 'f': {
        Value v = mkflt(va_arg(ap, double));
        n += num2str(b + n, 48, &v);
        break;
      }
      case 'c': b[n++] = (char)va_arg(ap, int); break;
      case 'p': n += sprintf(b + n, "%p", va_arg(ap, void *)); break;
      case 'U': n += sprintf(b + n, "U+%X", (unsigned)va_arg(ap, long)); break;
      case '%': b[n++] = '%'; break;
      default: b[n++] = '%'; b[n++] = *fmt; break;
    }
    fmt++;
  }
  va_end(ap);
  {
    Str *ts = str_newl(L, b, n);
    if (b != buf) free(b);
    return ts;
  }
}

/* ------------------------------------------------------------------ */
/* object constructors                                                 */
/* ------------------------------------------------------------------ */

static void link_gc(lua_State *L, GCObj *o, int tt) {
  o->tt = (uint8_t)tt; o->mark = 0; o->fin = 0;
  o->next = L->G->allgc; L->G->allgc = o;
}

Closure *cl_new(lua_State *L, Proto *p) {
  int n = p ? p->nupvals : 0;
  Closure *c = (Closure *)m_alloc(L, sizeof(Closure) + (n > 0 ? (n - 1) : 0) * sizeof(Upval *));
  link_gc(L, &c->h, T_FUN);
  c->p = p; c->nupvals = n;
  { int i; for (i = 0; i < n; i++) c->upvals[i] = NULL; }
  return c;
}

CClosure *ccl_new(lua_State *L, CFunc f, int nup) {
  CClosure *c = (CClosure *)m_alloc(L, sizeof(CClosure) + (nup > 0 ? (nup - 1) : 0) * sizeof(Value));
  link_gc(L, &c->h, T_CFUN);
  c->f = f; c->nupvals = nup; c->name = NULL;
  { int i; for (i = 0; i < nup; i++) c->upvals[i] = mknil(); }
  return c;
}

Proto *proto_new(lua_State *L) {
  Proto *p = m_new(L, Proto);
  link_gc(L, &p->h, 20);  /* private tag */
  p->is_vararg = 0; p->numparams = 0; p->maxstack = 2;
  p->code = NULL; p->ncode = 0; p->lineinfo = NULL;
  p->k = NULL; p->nk = 0; p->p = NULL; p->np = 0;
  p->upvals = NULL; p->nupvals = 0; p->locvars = NULL; p->nlocvars = 0;
  p->source = NULL; p->linedefined = 0; p->lastlinedefined = 0;
  return p;
}

Udata *ud_new(lua_State *L, size_t sz, int nuser) {
  Udata *u = (Udata *)m_alloc(L, sizeof(Udata) + sz + nuser * sizeof(Value));
  link_gc(L, &u->h, T_USERDATA);
  u->meta = NULL; u->len = sz; u->nuser = nuser;
  u->uv = (Value *)((char *)(u + 1) + sz);
  u->data = (sz > 0) ? (void *)(u + 1) : NULL;
  { int i; for (i = 0; i < nuser; i++) u->uv[i] = mknil(); }
  if (sz) memset(u->data, 0, sz);
  return u;
}

/* ------------------------------------------------------------------ */
/* garbage collection: simple mark & sweep                             */
/* ------------------------------------------------------------------ */

static void markvalue(lua_State *L, const Value *v);
static void markobj(lua_State *L, GCObj *o);

static void pushgray(lua_State *L, GCObj *o) {
  GlobalState *g = L->G;
  if (g->ngray >= g->graycap) {
    int nc = g->graycap ? g->graycap * 2 : 256;
    g->grayroots = (GCObj **)realloc(g->grayroots, nc * sizeof(GCObj *));
    g->graycap = nc;
  }
  g->grayroots[g->ngray++] = o;
}

static void markobj(lua_State *L, GCObj *o) {
  if (o == NULL || o->mark) return;
  o->mark = 1;
  if (o->tt == T_STR) return;   /* no children */
  pushgray(L, o);
}

static void markvalue(lua_State *L, const Value *v) {
  if (iscollectable(v)) markobj(L, v->u.gc);
}

/* weak table list built during propagate */
static Table **weaktabs; static int nweak, weakcap;

static void addweak(Table *t) {
  if (nweak >= weakcap) {
    weakcap = weakcap ? weakcap * 2 : 32;
    weaktabs = (Table **)realloc(weaktabs, weakcap * sizeof(Table *));
  }
  weaktabs[nweak++] = t;
}

static const char *weakmode(lua_State *L, Table *t) {
  const Value *mode;
  if (t->meta == NULL) return NULL;
  mode = tab_getmeta(L, t->meta, TM_MODE);
  if (mode && isstr(mode)) return strvalue(mode)->s;
  return NULL;
}

static void traversetable(lua_State *L, Table *t) {
  const char *mode = weakmode(L, t);
  uint32_t i;
  if (t->meta) markobj(L, &t->meta->h);
  if (mode && (strchr(mode, 'k') || strchr(mode, 'v'))) {
    addweak(t);
    if (!strchr(mode, 'v')) {
      /* weak keys: values are strong */
      for (i = 0; i < t->asize; i++) markvalue(L, &t->arr[i]);
      for (i = 0; i < t->nodesize; i++)
        if (!isnil(&t->node[i].val)) markvalue(L, &t->node[i].val);
    } else if (!strchr(mode, 'k')) {
      for (i = 0; i < t->nodesize; i++)
        if (!isnil(&t->node[i].val)) markvalue(L, &t->node[i].key);
    }
    return;
  }
  for (i = 0; i < t->asize; i++) markvalue(L, &t->arr[i]);
  for (i = 0; i < t->nodesize; i++) {
    Node *n = &t->node[i];
    if (!isnil(&n->val)) { markvalue(L, &n->key); markvalue(L, &n->val); }
  }
}

static void traverseproto(lua_State *L, Proto *p) {
  int i;
  markobj(L, (GCObj *)p->source);
  for (i = 0; i < p->nk; i++) markvalue(L, &p->k[i]);
  for (i = 0; i < p->np; i++) markobj(L, &p->p[i]->h);
  for (i = 0; i < p->nupvals; i++) markobj(L, (GCObj *)p->upvals[i].name);
  for (i = 0; i < p->nlocvars; i++) markobj(L, (GCObj *)p->locvars[i].name);
}

static void traversethread(lua_State *L, lua_State *th) {
  Value *o;
  Upval *uv;
  CallInfo *ci;
  if (th->stack == NULL) return;
  for (o = th->stack; o < th->top; o++) markvalue(L, o);
  for (ci = &th->base_ci; ci != NULL; ci = ci->next) {
    if (ci->top > th->top) {
      /* nothing: slots above top are dead */
    }
    if (ci == th->ci) break;
  }
  for (uv = th->openupval; uv; uv = (Upval *)uv->h.next) markobj(L, &uv->h);
  markvalue(L, &th->errval);
  if (th->caller) markobj(L, &th->caller->h);
}

static void propagate(lua_State *L) {
  GlobalState *g = L->G;
  while (g->ngray > 0) {
    GCObj *o = g->grayroots[--g->ngray];
    switch (o->tt) {
      case T_TAB: traversetable(L, (Table *)o); break;
      case T_FUN: {
        Closure *c = (Closure *)o;
        int i;
        if (c->p) markobj(L, &c->p->h);
        for (i = 0; i < c->nupvals; i++) markobj(L, (GCObj *)c->upvals[i]);
        break;
      }
      case T_CFUN: {
        CClosure *c = (CClosure *)o;
        int i;
        markobj(L, (GCObj *)c->name);
        for (i = 0; i < c->nupvals; i++) markvalue(L, &c->upvals[i]);
        break;
      }
      case T_USERDATA: {
        Udata *u = (Udata *)o;
        int i;
        if (u->meta) markobj(L, &u->meta->h);
        for (i = 0; i < u->nuser; i++) markvalue(L, &u->uv[i]);
        break;
      }
      case T_THREAD: traversethread(L, (lua_State *)o); break;
      case 20: traverseproto(L, (Proto *)o); break;
      case 21: { /* upvalue */
        Upval *uv = (Upval *)o;
        markvalue(L, uv->v);
        break;
      }
    }
  }
}

static void freeobj(lua_State *L, GCObj *o) {
  switch (o->tt) {
    case T_STR: {
      Str *s = (Str *)o;
      if (s->shrt) strt_remove(L->G, s);
      m_free(L, s, sizeof(Str) + s->len + 1);
      break;
    }
    case T_TAB: tab_free(L, (Table *)o); break;
    case T_FUN: {
      Closure *c = (Closure *)o;
      m_free(L, c, sizeof(Closure) + (c->nupvals > 0 ? c->nupvals - 1 : 0) * sizeof(Upval *));
      break;
    }
    case T_CFUN: {
      CClosure *c = (CClosure *)o;
      m_free(L, c, sizeof(CClosure) + (c->nupvals > 0 ? c->nupvals - 1 : 0) * sizeof(Value));
      break;
    }
    case T_USERDATA: {
      Udata *u = (Udata *)o;
      m_free(L, u, sizeof(Udata) + u->len + u->nuser * sizeof(Value));
      break;
    }
    case T_THREAD: {
      lua_State *th = (lua_State *)o;
      extern void th_free(lua_State *L, lua_State *th);
      th_free(L, th);
      break;
    }
    case 20: {
      Proto *p = (Proto *)o;
      m_freevec(L, p->code, p->ncode, uint32_t);
      m_freevec(L, p->lineinfo, p->ncode, int);
      m_freevec(L, p->k, p->nk, Value);
      m_freevec(L, p->p, p->np, Proto *);
      m_freevec(L, p->upvals, p->nupvals, UpvalDesc);
      m_freevec(L, p->locvars, p->nlocvars, LocVar);
      m_free(L, p, sizeof(Proto));
      break;
    }
    case 21: m_free(L, o, sizeof(Upval)); break;
  }
}

static void markroots(lua_State *L) {
  GlobalState *g = L->G;
  int i;
  markobj(L, &g->mainthread->h);
  markvalue(L, &g->registry);
  if (g->globals) markobj(L, &g->globals->h);
  if (g->stringmeta) markobj(L, &g->stringmeta->h);
  for (i = 0; i < TM_N; i++) markobj(L, (GCObj *)g->tmname[i]);
  markobj(L, (GCObj *)g->memerrmsg);
  /* mark all threads that are alive on the resume chain */
  { lua_State *t = g->current; while (t) { markobj(L, &t->h); t = t->caller; } }
}

static void clearweak(lua_State *L) {
  int i;
  for (i = 0; i < nweak; i++) {
    Table *t = weaktabs[i];
    const char *mode = weakmode(L, t);
    int wk = mode && strchr(mode, 'k');
    int wv = mode && strchr(mode, 'v');
    uint32_t j;
    if (wv) {
      for (j = 0; j < t->asize; j++) {
        Value *v = &t->arr[j];
        if (iscollectable(v) && !v->u.gc->mark) *v = mknil();
      }
    }
    for (j = 0; j < t->nodesize; j++) {
      Node *n = &t->node[j];
      if (isnil(&n->val)) continue;
      if ((wk && iscollectable(&n->key) && !n->key.u.gc->mark) ||
          (wv && iscollectable(&n->val) && !n->val.u.gc->mark)) {
        n->val = mknil();
      }
    }
  }
  nweak = 0;
}

/* separate objects to be finalized */
static void separatetobefnz(lua_State *L) {
  GlobalState *g = L->G;
  GCObj **p = &g->finobj;
  while (*p) {
    GCObj *o = *p;
    if (!o->mark && !o->fin) {
      *p = o->next;
      o->next = g->tobefnz; g->tobefnz = o;
      o->fin = 1;
    } else p = &o->next;
  }
}

static void callfinalizers(lua_State *L) {
  GlobalState *g = L->G;
  while (g->tobefnz) {
    GCObj *o = g->tobefnz;
    Value v = mkgc(o, o->tt);
    const Value *tm;
    g->tobefnz = o->next;
    /* move back to allgc; it may be resurrected */
    o->next = g->allgc; g->allgc = o;
    o->mark = 0;
    tm = get_metamethod(L, &v, TM_GC);
    if (tm && !isnil(tm)) {
      int oldstop = g->gcstopped;
      g->gcstopped = 1;
      ensurestack(L, 4);
      L->top[0] = *tm; L->top[1] = v; L->top += 2;
      {
        Value *f = L->top - 2;
        if (vm_pcall(L, f, 1, 0, 0) != 0) L->top = f;
      }
      g->gcstopped = oldstop;
    }
  }
}

static void sweep(lua_State *L) {
  GlobalState *g = L->G;
  GCObj **p = &g->allgc;
  while (*p) {
    GCObj *o = *p;
    if (o->mark) { o->mark = 0; p = &o->next; }
    else { *p = o->next; freeobj(L, o); }
  }
  p = &g->finobj;
  while (*p) { GCObj *o = *p; o->mark = 0; p = &o->next; }
  p = &g->tobefnz;
  while (*p) { GCObj *o = *p; o->mark = 0; p = &o->next; }
}

void gc_full(lua_State *L, int isemergency) {
  GlobalState *g = L->G;
  GCObj *o;
  if (g->inGC) return;
  g->inGC = 1;
  nweak = 0;
  markroots(L);
  /* objects with finalizers: their contents remain reachable until finalized */
  for (o = g->tobefnz; o; o = o->next) markobj(L, o);
  propagate(L);
  separatetobefnz(L);
  for (o = g->tobefnz; o; o = o->next) markobj(L, o);
  propagate(L);
  clearweak(L);
  sweep(L);
  g->gcthreshold = g->totalbytes * 2;
  if (g->gcthreshold < (1 << 20)) g->gcthreshold = (1 << 20);
  g->inGC = 0;
  if (!isemergency) callfinalizers(L);
}

void gc_step(lua_State *L) { gc_full(L, 0); }

void gc_checkfin(lua_State *L, Value *o, Table *mt) {
  GlobalState *g = L->G;
  GCObj **p;
  GCObj *obj = o->u.gc;
  if (mt == NULL) return;
  if (tab_getmeta(L, mt, TM_GC) == NULL) return;
  if (obj->fin) return;
  /* move object from allgc to finobj */
  for (p = &g->allgc; *p; p = &(*p)->next) {
    if (*p == obj) {
      *p = obj->next;
      obj->next = g->finobj; g->finobj = obj;
      return;
    }
  }
}

void gc_freeall(lua_State *L) {
  GlobalState *g = L->G;
  GCObj *o = g->allgc;
  while (o) { GCObj *n = o->next; freeobj(L, o); o = n; }
  o = g->finobj;
  while (o) { GCObj *n = o->next; freeobj(L, o); o = n; }
  o = g->tobefnz;
  while (o) { GCObj *n = o->next; freeobj(L, o); o = n; }
  g->allgc = g->finobj = g->tobefnz = NULL;
}

