static uint32_t hashint(lint i) {
  uint64_t u = (uint64_t)i;
  u = (u ^ (u >> 32)) * 0x9E3779B97F4A7C15ull;
  return (uint32_t)(u ^ (u >> 29));
}

static uint32_t hashflt(lnum n) {
  lint i;
  if (n == (lnum)(lint)n && n >= -9.2233720368547758e18 && n < 9.2233720368547758e18) {
    i = (lint)n;
    return hashint(i);
  } else {
    uint64_t u;
    memcpy(&u, &n, 8);
    u = (u ^ (u >> 32)) * 0x9E3779B97F4A7C15ull;
    return (uint32_t)(u ^ (u >> 29));
  }
}

static uint32_t hashptr(const void *p) {
  uint64_t u = (uint64_t)(uintptr_t)p;
  u = (u ^ (u >> 32)) * 0x9E3779B97F4A7C15ull;
  return (uint32_t)(u ^ (u >> 29));
}

static uint32_t hashvalue(const Value *k) {
  switch (k->tt) {
    case T_NIL: return 0;
    case T_FALSE: return 1;
    case T_TRUE: return 2;
    case T_INT: return hashint(ivalue(k));
    case T_FLT: return hashflt(fltvalue(k));
    case T_STR: return strvalue(k)->hash;
    case T_LIGHTUD: return hashptr(k->u.p);
    default: return hashptr(k->u.gc);
  }
}

static int rawvaleq(const Value *a, const Value *b) {
  if (a->tt != b->tt) {
    if (a->tt == T_INT && b->tt == T_FLT)
      return (lnum)ivalue(a) == fltvalue(b);
    if (a->tt == T_FLT && b->tt == T_INT)
      return fltvalue(a) == (lnum)ivalue(b);
    return 0;
  }
  switch (a->tt) {
    case T_NIL: case T_FALSE: case T_TRUE: return 1;
    case T_INT: return ivalue(a) == ivalue(b);
    case T_FLT: return fltvalue(a) == fltvalue(b);
    case T_STR: return str_eq(strvalue(a), strvalue(b));
    case T_LIGHTUD: return a->u.p == b->u.p;
    default: return a->u.gc == b->u.gc;
  }
}

Table *tab_new(lua_State *L) { return tab_newsz(L, 0, 0); }

static uint32_t ceilpow2(uint32_t n) {
  uint32_t p = 1;
  while (p < n) p <<= 1;
  return p;
}

static void setnodevector(lua_State *L, Table *t, uint32_t size) {
  if (size == 0) {
    t->node = dummynode; t->lsizenode = 0; t->nodesize = 0; t->lastfree = 0;
  } else {
    uint32_t i;
    uint32_t sz = ceilpow2(size);
    uint32_t lsz = 0;
    while ((1u << lsz) < sz) lsz++;
    t->node = m_newvec(L, sz, Node);
    for (i = 0; i < sz; i++) {
      t->node[i].key = mknil();
      t->node[i].val = mknil();
      t->node[i].next = 0;
    }
    t->lsizenode = lsz; t->nodesize = sz; t->lastfree = (int32_t)sz;
  }
}

Table *tab_newsz(lua_State *L, int narr, int nrec) {
  Table *t = m_new(L, Table);
  t->h.tt = T_TAB; t->h.mark = 0; t->h.fin = 0;
  t->h.next = L->G->allgc; L->G->allgc = &t->h;
  t->flags = 0; t->meta = NULL;
  t->arr = NULL; t->asize = 0; t->alimit = 0;
  setnodevector(L, t, (uint32_t)nrec);
  if (narr > 0) {
    int i;
    t->arr = m_newvec(L, narr, Value);
    t->asize = (uint32_t)narr;
    for (i = 0; i < narr; i++) t->arr[i] = mknil();
  }
  return t;
}

void tab_free(lua_State *L, Table *t) {
  if (!isdummy(t)) m_freevec(L, t->node, t->nodesize, Node);
  m_freevec(L, t->arr, t->asize, Value);
  m_free(L, t, sizeof(Table));
}

static Node *mainposition(Table *t, const Value *k) {
  return &t->node[hashvalue(k) & (t->nodesize - 1)];
}

static Node *getfreepos(Table *t) {
  while (t->lastfree > 0) {
    t->lastfree--;
    if (isnil(&t->node[t->lastfree].key))
      return &t->node[t->lastfree];
  }
  return NULL;
}

/* find node holding key k, or NULL */
static Node *findnode(Table *t, const Value *k) {
  Node *n;
  if (isdummy(t)) return NULL;
  n = mainposition(t, k);
  for (;;) {
    if (rawvaleq(&n->key, k) && !isnil(&n->key)) return n;
    if (n->next == 0) return NULL;
    n += n->next;
  }
}

static const Value *getgeneric(Table *t, const Value *k) {
  Node *n = findnode(t, k);
  return n ? &n->val : NULL;
}

const Value *tab_getint(Table *t, lint k) {
  if ((uint64_t)(k - 1) < (uint64_t)t->asize)
    return &t->arr[k - 1];
  else {
    Value v = mkint(k);
    return getgeneric(t, &v);
  }
}

const Value *tab_getstr(Table *t, Str *k) {
  Value v = mkstr(k);
  if (isdummy(t)) return NULL;
  {
    Node *n = &t->node[k->hash & (t->nodesize - 1)];
    for (;;) {
      if (isstr(&n->key) && str_eq(strvalue(&n->key), k)) return &n->val;
      if (n->next == 0) return NULL;
      n += n->next;
    }
  }
  (void)v;
}

const Value *tab_get(Table *t, const Value *k) {
  switch (k->tt) {
    case T_NIL: return NULL;
    case T_STR: return tab_getstr(t, strvalue(k));
    case T_INT: return tab_getint(t, ivalue(k));
    case T_FLT: {
      lnum n = fltvalue(k);
      lint i;
      if (flt2int(n, &i, 0)) return tab_getint(t, i);
      if (n != n) return NULL;   /* NaN never present */
      return getgeneric(t, k);
    }
    default: return getgeneric(t, k);
  }
}

/* count keys for rehash */
static uint32_t countint(const Value *k, uint32_t *nums) {
  lint i;
  if (k->tt == T_INT) i = ivalue(k);
  else if (k->tt == T_FLT) { if (!flt2int(fltvalue(k), &i, 0)) return 0; }
  else return 0;
  if (i >= 1 && i <= (lint)INT32_MAX) {
    uint32_t lg = 0;
    uint32_t ii = (uint32_t)i;
    while ((1u << lg) < ii) lg++;
    nums[lg]++;
    return 1;
  }
  return 0;
}

static uint32_t computesizes(uint32_t *nums, uint32_t *pna) {
  int i;
  uint32_t twotoi, a = 0, na = 0, optimal = 0;
  for (i = 0, twotoi = 1; twotoi > 0 && *pna > twotoi / 2; i++, twotoi *= 2) {
    a += nums[i];
    if (a > twotoi / 2) { optimal = twotoi; na = a; }
  }
  *pna = na;
  return optimal;
}

static void reinsert(lua_State *L, Table *ot, Table *t) {
  uint32_t i;
  for (i = 0; i < ot->asize; i++)
    if (!isnil(&ot->arr[i])) tab_setint(L, t, (lint)i + 1, &ot->arr[i]);
  for (i = 0; i < ot->nodesize; i++) {
    Node *n = &ot->node[i];
    if (!isnil(&n->val)) tab_set(L, t, &n->key, &n->val);
  }
}

void tab_resize(lua_State *L, Table *t, uint32_t nasize, uint32_t nhsize) {
  Table newt;
  uint32_t i;
  Value *oldarr = t->arr;
  uint32_t oldasize = t->asize;
  Node *oldnode = t->node;
  uint32_t oldnodesize = t->nodesize;
  newt = *t;
  newt.arr = NULL; newt.asize = 0;
  setnodevector(L, &newt, nhsize);
  if (nasize > 0) {
    newt.arr = m_newvec(L, nasize, Value);
    newt.asize = nasize;
    for (i = 0; i < nasize; i++) newt.arr[i] = mknil();
  }
  /* copy array part that fits */
  for (i = 0; i < oldasize && i < nasize; i++) newt.arr[i] = oldarr[i];
  /* move the rest into the new table */
  {
    Table *tmp = t;
    Table save = *t;
    *t = newt;
    /* re-insert overflow from old array */
    for (i = nasize; i < oldasize; i++)
      if (!isnil(&oldarr[i])) tab_setint(L, t, (lint)i + 1, &oldarr[i]);
    for (i = 0; i < oldnodesize; i++) {
      Node *n = &oldnode[i];
      if (!isnil(&n->val)) tab_set(L, t, &n->key, &n->val);
    }
    (void)tmp; (void)save;
  }
  if (oldnodesize > 0) m_freevec(L, oldnode, oldnodesize, Node);
  m_freevec(L, oldarr, oldasize, Value);
  (void)reinsert;
}

static void rehash(lua_State *L, Table *t, const Value *ek) {
  uint32_t nums[40];
  uint32_t i, totaluse, na, asize;
  for (i = 0; i < 40; i++) nums[i] = 0;
  na = 0; totaluse = 0;
  /* count array part */
  for (i = 0; i < t->asize; i++) {
    if (!isnil(&t->arr[i])) {
      uint32_t lg = 0, ii = i + 1;
      while ((1u << lg) < ii) lg++;
      nums[lg]++; na++; totaluse++;
    }
  }
  for (i = 0; i < t->nodesize; i++) {
    Node *n = &t->node[i];
    if (!isnil(&n->val)) { na += countint(&n->key, nums); totaluse++; }
  }
  na += countint(ek, nums); totaluse++;
  asize = computesizes(nums, &na);
  tab_resize(L, t, asize, totaluse - na);
}

static Value *newkey(lua_State *L, Table *t, const Value *k) {
  Node *mp;
  if (isdummy(t)) {
    rehash(L, t, k);
    return (Value *)tab_get(t, k) ? (Value *)tab_get(t, k) : newkey(L, t, k);
  }
  mp = mainposition(t, k);
  if (!isnil(&mp->val) || isdummy(t)) {
    Node *f = getfreepos(t);
    Node *othern;
    if (f == NULL) {
      rehash(L, t, k);
      { const Value *p = tab_get(t, k);
        if (p) return (Value *)p; }
      return newkey(L, t, k);
    }
    othern = mainposition(t, &mp->key);
    if (othern != mp) {
      /* colliding node is out of its main position: move it to free pos */
      while (othern + othern->next != mp) othern += othern->next;
      othern->next = (int32_t)(f - othern);
      *f = *mp;
      if (mp->next != 0) { f->next += (int32_t)(mp - f); mp->next = 0; }
      mp->val = mknil();
    } else {
      if (mp->next != 0) f->next = (int32_t)((mp + mp->next) - f);
      mp->next = (int32_t)(f - mp);
      mp = f;
    }
  }
  mp->key = *k;
  mp->val = mknil();
  return &mp->val;
}

static Value *getslot_for_set(lua_State *L, Table *t, const Value *k) {
  Node *n;
  if (!isdummy(t)) {
    n = findnode(t, k);
    if (n) return &n->val;
  }
  return newkey(L, t, k);
}

void tab_setint(lua_State *L, Table *t, lint k, const Value *v) {
  if ((uint64_t)(k - 1) < (uint64_t)t->asize) { t->arr[k - 1] = *v; return; }
  {
    Value key = mkint(k);
    Node *n = isdummy(t) ? NULL : findnode(t, &key);
    if (n) { n->val = *v; return; }
    if (isnil(v)) return;
    /* maybe grow array */
    if (k == (lint)t->asize + 1 && k < (lint)INT32_MAX) {
      uint32_t newsize = t->asize ? t->asize * 2 : 4;
      uint32_t i;
      uint32_t cnt = 0;
      /* only grow if the hash part has following integer keys or array is dense */
      Value *na = m_newvec(L, newsize, Value);
      for (i = 0; i < t->asize; i++) na[i] = t->arr[i];
      for (i = t->asize; i < newsize; i++) na[i] = mknil();
      m_freevec(L, t->arr, t->asize, Value);
      t->arr = na; t->asize = newsize;
      t->arr[k - 1] = *v;
      /* migrate integer keys from hash to array */
      for (i = 0; i < t->nodesize; i++) {
        Node *nd = &t->node[i];
        if (!isnil(&nd->val) && isint(&nd->key)) {
          lint ik = ivalue(&nd->key);
          if (ik >= 1 && (uint64_t)ik <= (uint64_t)newsize) {
            t->arr[ik - 1] = nd->val;
            nd->val = mknil();
            cnt++;
          }
        }
      }
      return;
    }
    *newkey(L, t, &key) = *v;
  }
}

void tab_setstr(lua_State *L, Table *t, Str *k, const Value *v) {
  Value key = mkstr(k);
  Value *slot;
  if (!isdummy(t)) {
    Node *n = &t->node[k->hash & (t->nodesize - 1)];
    for (;;) {
      if (isstr(&n->key) && str_eq(strvalue(&n->key), k)) { n->val = *v; t->flags = 0; return; }
      if (n->next == 0) break;
      n += n->next;
    }
  }
  if (isnil(v)) return;
  slot = newkey(L, t, &key);
  *slot = *v;
  t->flags = 0;
}

void tab_set(lua_State *L, Table *t, const Value *k, const Value *v) {
  switch (k->tt) {
    case T_STR: tab_setstr(L, t, strvalue(k), v); return;
    case T_INT: tab_setint(L, t, ivalue(k), v); return;
    case T_FLT: {
      lint i;
      if (flt2int(fltvalue(k), &i, 0)) { tab_setint(L, t, i, v); return; }
      break;
    }
    default: break;
  }
  {
    Node *n = isdummy(t) ? NULL : findnode(t, k);
    if (n) { n->val = *v; t->flags = 0; return; }
    if (isnil(v)) return;
    *newkey(L, t, k) = *v;
    t->flags = 0;
  }
}

lint tab_len(Table *t) {
  uint32_t asize = t->asize;
  if (asize > 0 && isnil(&t->arr[asize - 1])) {
    /* binary search in array part */
    uint32_t lo = 0, hi = asize - 1;
    /* invariant: arr[lo-1] non-nil (or lo==0), arr[hi] nil */
    while (hi - lo > 0) {
      uint32_t m = (lo + hi) / 2;
      if (isnil(&t->arr[m])) hi = m; else lo = m + 1;
    }
    return (lint)lo;
  }
  /* array part is full (or empty): check hash part */
  if (isdummy(t)) return (lint)asize;
  {
    lint i = (lint)asize;
    lint j = i + 1;
    while (1) {
      const Value *v = tab_getint(t, j);
      if (v == NULL || isnil(v)) break;
      i = j;
      if (j > (lint)1 << 40) {
        /* linear search */
        i = 1;
        while (1) { const Value *w = tab_getint(t, i); if (w && !isnil(w)) i++; else break; }
        return i - 1;
      }
      j *= 2;
    }
    while (j - i > 1) {
      lint m = (i + j) / 2;
      const Value *v = tab_getint(t, m);
      if (v && !isnil(v)) i = m; else j = m;
    }
    return i;
  }
}

/* iteration: array part first, then nodes */
int tab_next(lua_State *L, Table *t, Value *key, Value *out) {
  uint32_t i = 0;
  if (isnil(key)) i = 0;
  else {
    /* find index of key */
    lint ik;
    int found = 0;
    if (isint(key)) ik = ivalue(key);
    else if (isflt(key) && flt2int(fltvalue(key), &ik, 0)) { }
    else ik = 0;
    if (ik >= 1 && (uint64_t)ik <= (uint64_t)t->asize) { i = (uint32_t)ik; found = 1; }
    if (!found) {
      Node *n = findnode(t, key);
      if (n == NULL) return -1;   /* invalid key */
      i = t->asize + (uint32_t)(n - t->node) + 1;
    }
  }
  for (; i < t->asize; i++) {
    if (!isnil(&t->arr[i])) {
      out[0] = mkint((lint)i + 1);
      out[1] = t->arr[i];
      return 1;
    }
  }
  for (i = i - t->asize; i < t->nodesize; i++) {
    if (!isnil(&t->node[i].val)) {
      out[0] = t->node[i].key;
      out[1] = t->node[i].val;
      return 1;
    }
  }
  return 0;
}

