/* table.c -- Lua tables: array part + hash part.
** The sizing/hashing policy mirrors the observable behaviour of the
** reference implementation (deterministic iteration order for
** non-string keys, border computation for '#').
*/
#include <string.h>
#include <math.h>
#include <limits.h>
#include "mlua.h"

static Node dummynode_ = { {{0}, T_NIL}, {{0}, T_NIL}, 0 };
#define dummynode (&dummynode_)
#define isdummy(t) ((t)->nodesize == 0)

#define MAXABITS  30
#define MAXASIZE  (1u << MAXABITS)

static int l_hashfloat(lnum n) {
  int i;
  lint ni;
  n = frexp(n, &i) * -(lnum)INT_MIN;
  if (!(n >= (lnum)INT64_MIN && n < -(lnum)INT64_MIN && (ni = (lint)n, 1))) {
    return 0;   /* inf / nan */
  } else {
    unsigned int u = (unsigned int)i + (unsigned int)ni;
    return (int)(u <= (unsigned int)INT_MAX ? u : ~u);
  }
}

static Node *hashmod(Table *t, uint64_t n) {
  return &t->node[n % ((uint64_t)((t->nodesize - 1) | 1))];
}

static Node *hashpow2(Table *t, uint64_t n) {
  return &t->node[n & (t->nodesize - 1)];
}

static Node *mainposition(Table *t, const Value *k) {
  switch (k->tt) {
    case T_NIL: return &t->node[0];
    case T_FALSE: return hashpow2(t, 0);
    case T_TRUE: return hashpow2(t, 1);
    case T_INT: return hashmod(t, (uint64_t)ivalue(k));
    case T_FLT: return hashmod(t, (uint64_t)(unsigned)l_hashfloat(fltvalue(k)));
    case T_STR: return hashpow2(t, strvalue(k)->hash);
    case T_LIGHTUD: return hashmod(t, (uint64_t)(uintptr_t)k->u.p);
    case T_CFUN: return hashmod(t, (uint64_t)(uintptr_t)k->u.gc);
    default: return hashmod(t, (uint64_t)(uintptr_t)k->u.gc);
  }
}

static int rawvaleq(const Value *a, const Value *b) {
  if (a->tt != b->tt) {
    if (a->tt == T_INT && b->tt == T_FLT) return (lnum)ivalue(a) == fltvalue(b);
    if (a->tt == T_FLT && b->tt == T_INT) return fltvalue(a) == (lnum)ivalue(b);
    return 0;
  }
  switch (a->tt) {
    case T_NIL: case T_FALSE: case T_TRUE: return 1;
    case T_INT: return ivalue(a) == ivalue(b);
    case T_FLT: return fltvalue(a) == fltvalue(b);
    case T_STR: return str_eq(strvalue(a), strvalue(b));
    case T_LIGHTUD: return a->u.p == b->u.p;
    default: return a->u.gc == b->u.gc;
  }
}

static uint32_t ceilpow2(uint32_t n) {
  uint32_t p = 1;
  while (p < n) p <<= 1;
  return p;
}

static void setnodevector(lua_State *L, Table *t, uint32_t size) {
  if (size == 0) {
    t->node = dummynode; t->lsizenode = 0; t->nodesize = 0; t->lastfree = 0;
  } else {
    uint32_t i, sz = ceilpow2(size), lsz = 0;
    while ((1u << lsz) < sz) lsz++;
    t->node = m_newvec(L, sz, Node);
    for (i = 0; i < sz; i++) {
      t->node[i].key = mknil(); t->node[i].val = mknil(); t->node[i].next = 0;
    }
    t->lsizenode = lsz; t->nodesize = sz; t->lastfree = (int32_t)sz;
  }
}

Table *tab_newsz(lua_State *L, int narr, int nrec) {
