      if (j > (lint)1 << 40) {
        i = (lint)asize + 1;
        while (1) { const Value *w = tab_getint(t, i); if (w && !isnil(w)) i++; else break; }
        return i - 1;
      }
      j *= 2;
    }
    while (j - i > 1) {
      lint m = (i + j) / 2;
      const Value *v = tab_getint(t, m);
      if (v && !isnil(v)) i = m; else j = m;
    }
    return i;
  }
}

int tab_next(lua_State *L, Table *t, Value *key, Value *out) {
  uint32_t i = 0;
  (void)L;
  if (!isnil(key)) {
    lint ik = 0;
    int inarr = 0;
    if (isint(key)) { ik = ivalue(key); inarr = 1; }
    else if (isflt(key) && flt2int(fltvalue(key), &ik, 0)) inarr = 1;
    if (inarr && ik >= 1 && (uint64_t)ik <= (uint64_t)t->asize) i = (uint32_t)ik;
    else {
      Node *n = findnode(t, key);
      if (n == NULL) return -1;
      i = t->asize + (uint32_t)(n - t->node) + 1;
    }
  }
  for (; i < t->asize; i++) {
    if (!isnil(&t->arr[i])) {
      out[0] = mkint((lint)i + 1); out[1] = t->arr[i]; return 1;
    }
  }
  for (i = i - t->asize; i < t->nodesize; i++) {
    if (!isnil(&t->node[i].val)) {
      out[0] = t->node[i].key; out[1] = t->node[i].val; return 1;
    }
  }
  return 0;
}
